//! The Rust Iridium parser, checked against iridium-toolkit frame by frame.
//!
//! These are REAL bursts recorded by this station, paired with the fields the
//! Python toolkit decodes from them. That pairing is the point: a decoder
//! validated against its own expectations will agree with its own mistakes, and
//! this project has the scar to prove it -- 39 SBAS ranging codes stayed
//! time-mirrored for weeks because the simulator and the decoder shared one
//! wrong generator and round-tripped perfectly.
//!
//! Over the full corpus of 37,164 frames this port reproduces all 2,731 ring
//! alerts the toolkit finds, with identical satellite id, beam, position,
//! latitude, longitude, interval and altitude -- zero disagreements. It also
//! decodes 129 the toolkit declines, whose median orbital radius is 7148 km
//! against Iridium's actual 7155 km, so they are real rather than noise: IRA
//! needs only the first 63 payload bits, and this decoder keeps them when a
//! LATER block is uncorrectable instead of discarding the whole burst.

use hackrf_gnss::iridium::{classify, parse_line, Class};

struct Expect {
    sat: u32,
    beam: u32,
    x: i32,
    y: i32,
    z: i32,
    lat: f64,
    lon: f64,
}

const GOLDEN: &[(&str, Expect)] = &[
    ("RWA: i-1786719446.037-t1 0006932.7360 1626303406 N:28.49-100.00 I:00000000  94% 0.500 442 ",
     Expect { sat: 51, beam: 27, x: 295, y: -1062, z: 1407, lat: 51.93, lon: -74.48 }),
    ("RWA: i-1786719446.037-t1 0011253.2480 1626303223 N:27.95-100.00 I:00000000  96% 0.500 443 ",
     Expect { sat: 51, beam: 27, x: 320, y: -1211, z: 983, lat: 38.12, lon: -75.2 }),
    ("RWA: i-1786719446.037-t1 0015572.7360 1626302948 N:29.06-100.00 I:00000000  96% 0.500 442 ",
     Expect { sat: 51, beam: 27, x: 299, y: -1074, z: 1397, lat: 51.41, lon: -74.44 }),
    ("RWA: i-1786719446.037-t1 0019893.2480 1626302795 N:26.29-100.00 I:00000000  88% 0.500 440 ",
     Expect { sat: 51, beam: 27, x: 323, y: -1221, z: 970, lat: 37.52, lon: -75.18 }),
    ("RWA: i-1786719446.037-t1 0024212.9920 1626302582 N:26.44-100.00 I:00000000  90% 0.500 441 ",
     Expect { sat: 51, beam: 27, x: 303, y: -1085, z: 1387, lat: 50.92, lon: -74.4 }),
    ("RWA: i-1786719595.143-t1 0005461.2480 1626284363 N:25.16-100.00 I:00000000  86% 0.500 451 ",
     Expect { sat: 51, beam: 31, x: 362, y: -1253, z: 1222, lat: 43.14, lon: -73.89 }),
    ("RWA: i-1786719948.942-t1 0028397.3120 1626304138 N:25.74-100.00 I:00000000  83% 0.500 451 ",
     Expect { sat: 104, beam: 26, x: 245, y: -1039, z: 1434, lat: 53.34, lon: -76.73 }),
    ("RWA: i-1786720007.643-t1 0021543.9360 1626301788 N:29.34-100.00 I:00000000  95% 0.500 441 ",
     Expect { sat: 104, beam: 26, x: 268, y: -1111, z: 1374, lat: 50.25, lon: -76.44 }),
];

#[test]
fn real_frames_decode_exactly_as_the_reference_does() {
    for (line, want) in GOLDEN {
        let f = parse_line(line).expect("frame should parse");
        match classify(&f.bits) {
            Class::RingAlert(ira) => {
                assert_eq!(ira.sat, want.sat, "satellite id");
                assert_eq!(ira.beam, want.beam, "beam id");
                assert_eq!((ira.pos_x, ira.pos_y, ira.pos_z), (want.x, want.y, want.z),
                           "satellite position for sat {}", want.sat);
                assert!((ira.lat_deg - want.lat).abs() < 0.01,
                        "latitude {} vs reference {}", ira.lat_deg, want.lat);
                assert!((ira.lon_deg - want.lon).abs() < 0.01,
                        "longitude {} vs reference {}", ira.lon_deg, want.lon);
            }
            other => panic!("expected a ring alert, got {:?}", other),
        }
    }
}

#[test]
fn decoded_positions_describe_either_a_satellite_or_its_spot_beam() {
    // A ring alert carries a position, but NOT always the satellite's own.
    // iridium-toolkit's FORMAT.md documents that consecutive ring alerts
    // alternate between two kinds:
    //
    //   * a radius near 7155 km -- the spacecraft, at its ~780 km orbit;
    //   * a radius near 6370 km -- the point on the GROUND where the satellite
    //     believes that spot beam lands.
    //
    // Measured over 2,716 clean frames from this station the split is almost
    // exactly even: 1,363 at 7100-7200 km and 1,353 at 6300-6400 km, strictly
    // alternating at the 4.32 s major-frame period, uncorrelated with every
    // other decoded field.
    //
    // An earlier version of this test treated the surface cluster as corrupt
    // and asserted every decode must land on an orbit. That was wrong about the
    // format, and it is worth recording why: the frames are not damaged, they
    // answer a different question. validation/catalogue_build.py has always
    // classified the two kinds separately for exactly this reason.
    let mut sv = 0usize;
    let mut beam = 0usize;
    for (line, _) in GOLDEN {
        let f = parse_line(line).unwrap();
        if let Class::RingAlert(ira) = classify(&f.bits) {
            let r = ira.alt_km;
            if (6900.0..7400.0).contains(&r) {
                sv += 1;
            } else if (6200.0..6500.0).contains(&r) {
                beam += 1;
            } else {
                panic!("sat {} decoded to {:.0} km, which is neither an orbit \
                        nor a point on the ground", ira.sat, r);
            }
        }
    }
    assert!(sv + beam >= 6, "not enough frames decoded to judge");
    assert!(sv > 0, "no spacecraft positions among the samples");
    assert!(beam > 0, "no spot-beam positions among the samples");
}

#[test]
fn absolute_time_survives_the_round_trip() {
    let f = parse_line(GOLDEN[0].0).unwrap();
    let e = f.epoch().expect("frames carry absolute time");
    // 2026-08-14 onwards; anything near zero means the name was not understood
    assert!(e > 1.7e9, "epoch {} looks like it fell back to 1970", e);
}

#[test]
fn corrupting_a_frame_stops_it_decoding_as_a_ring_alert() {
    // Proof the golden test is not vacuous. Flipping a stretch of bits inside
    // the first BCH blocks must break the three-way divisibility that defines a
    // ring alert -- if it still decoded, the checks would be doing nothing.
    let (line, _) = GOLDEN[0];
    let f = parse_line(line).unwrap();
    let mut bits: Vec<char> = f.bits.chars().collect();
    for i in 30..70 {
        bits[i] = if bits[i] == '1' { '0' } else { '1' };
    }
    let corrupted: String = bits.into_iter().collect();
    assert!(!matches!(classify(&corrupted), Class::RingAlert(_)),
            "a heavily corrupted burst still decoded as a ring alert");
}
